CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, root_path TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS workflows (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', current_version_id TEXT, status TEXT NOT NULL DEFAULT 'active', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS workflow_versions (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id) ON DELETE RESTRICT, version_no INTEGER NOT NULL, content_hash TEXT NOT NULL, source_path TEXT NOT NULL, bundle_path TEXT NOT NULL, manifest_json TEXT NOT NULL, sdk_version TEXT NOT NULL, dependency_lock_hash TEXT, created_at INTEGER NOT NULL, UNIQUE(workflow_id, version_no), UNIQUE(workflow_id, content_hash));
CREATE TABLE IF NOT EXISTS workflow_drafts (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, workflow_id TEXT REFERENCES workflows(id) ON DELETE SET NULL, base_version_id TEXT REFERENCES workflow_versions(id) ON DELETE SET NULL, root_path TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0, content_hash TEXT, status TEXT NOT NULL DEFAULT 'draft', check_result_json TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, workflow_version_id TEXT NOT NULL REFERENCES workflow_versions(id) ON DELETE RESTRICT, trigger_id TEXT, retry_of_run_id TEXT REFERENCES runs(id) ON DELETE SET NULL, status TEXT NOT NULL, input_ref TEXT, output_ref TEXT, cancel_requested_at INTEGER, cancel_reason TEXT, claim_owner TEXT, claim_until INTEGER, worker_generation INTEGER, created_at INTEGER NOT NULL, started_at INTEGER, ended_at INTEGER);
CREATE TABLE IF NOT EXISTS step_runs (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE RESTRICT, step_id TEXT NOT NULL, step_instance_key TEXT NOT NULL, iteration_key TEXT, node_type TEXT NOT NULL, node_version TEXT NOT NULL, config_snapshot_ref TEXT, status TEXT NOT NULL, input_ref TEXT, output_ref TEXT, created_at INTEGER NOT NULL, started_at INTEGER, ended_at INTEGER, UNIQUE(run_id, step_instance_key));
CREATE TABLE IF NOT EXISTS step_attempts (id TEXT PRIMARY KEY, step_run_id TEXT NOT NULL REFERENCES step_runs(id) ON DELETE RESTRICT, attempt_no INTEGER NOT NULL, status TEXT NOT NULL, input_ref TEXT, output_ref TEXT, error_json TEXT, timed_out INTEGER NOT NULL DEFAULT 0, worker_generation INTEGER, created_at INTEGER NOT NULL, started_at INTEGER, ended_at INTEGER, UNIQUE(step_run_id, attempt_no));
CREATE TABLE IF NOT EXISTS tool_invocations (id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES step_attempts(id) ON DELETE RESTRICT, sequence_no INTEGER NOT NULL, tool_id TEXT NOT NULL, tool_version TEXT NOT NULL, input_ref TEXT, output_ref TEXT, side_effect_class TEXT NOT NULL, idempotency_key TEXT, external_id TEXT, result_certainty TEXT, status TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(attempt_id, sequence_no));
CREATE TABLE IF NOT EXISTS run_events (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE RESTRICT, sequence_no INTEGER NOT NULL, step_id TEXT, attempt_id TEXT REFERENCES step_attempts(id) ON DELETE SET NULL, event_type TEXT NOT NULL, payload_ref TEXT, payload_json TEXT, created_at INTEGER NOT NULL, UNIQUE(run_id, sequence_no));
CREATE TABLE IF NOT EXISTS triggers (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id) ON DELETE RESTRICT, type TEXT NOT NULL, version_policy TEXT NOT NULL, config_json TEXT NOT NULL, timezone TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, next_fire_at INTEGER, misfire_policy TEXT NOT NULL DEFAULT 'skip', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS trigger_occurrences (id TEXT PRIMARY KEY, trigger_id TEXT NOT NULL REFERENCES triggers(id) ON DELETE RESTRICT, occurrence_key TEXT NOT NULL, scheduled_for INTEGER NOT NULL, run_id TEXT REFERENCES runs(id) ON DELETE SET NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(trigger_id, occurrence_key));
CREATE TABLE IF NOT EXISTS incoming_events (id TEXT PRIMARY KEY, source TEXT NOT NULL, event_id TEXT NOT NULL, event_name TEXT NOT NULL, payload_ref TEXT, payload_hash TEXT NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(source, event_id));
CREATE TABLE IF NOT EXISTS incoming_event_deliveries (id TEXT PRIMARY KEY, incoming_event_id TEXT NOT NULL REFERENCES incoming_events(id) ON DELETE RESTRICT, trigger_id TEXT NOT NULL REFERENCES triggers(id) ON DELETE RESTRICT, run_id TEXT REFERENCES runs(id) ON DELETE SET NULL, status TEXT NOT NULL, error TEXT, created_at INTEGER NOT NULL, UNIQUE(incoming_event_id, trigger_id));
CREATE TABLE IF NOT EXISTS authoring_sessions (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, draft_id TEXT NOT NULL REFERENCES workflow_drafts(id) ON DELETE RESTRICT, status TEXT NOT NULL, model_config_ref TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS authoring_messages (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES authoring_sessions(id) ON DELETE RESTRICT, sequence_no INTEGER NOT NULL, role TEXT NOT NULL, content_ref TEXT, tool_call_json TEXT, created_at INTEGER NOT NULL, UNIQUE(session_id, sequence_no));
CREATE TABLE IF NOT EXISTS tool_configs (id TEXT PRIMARY KEY, tool_id TEXT NOT NULL, version TEXT NOT NULL, config_json TEXT NOT NULL, permission_json TEXT NOT NULL, secret_ref TEXT, enabled INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, UNIQUE(tool_id, version));
CREATE TABLE IF NOT EXISTS agent_profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, config_json TEXT NOT NULL, allowed_tools_json TEXT NOT NULL, secret_ref TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS artifacts (id TEXT PRIMARY KEY, run_id TEXT REFERENCES runs(id) ON DELETE SET NULL, step_id TEXT, attempt_id TEXT REFERENCES step_attempts(id) ON DELETE SET NULL, path TEXT NOT NULL, size INTEGER NOT NULL, hash TEXT NOT NULL, mime TEXT NOT NULL, retention_policy TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit_actions (id TEXT PRIMARY KEY, action_type TEXT NOT NULL, actor TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, metadata_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_keys (key TEXT PRIMARY KEY, operation TEXT NOT NULL, request_hash TEXT NOT NULL, resource_id TEXT, response_ref TEXT, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_runs_status_created ON runs(status, created_at);
CREATE INDEX IF NOT EXISTS idx_runs_claim_until ON runs(claim_until);
CREATE INDEX IF NOT EXISTS idx_runs_version_created ON runs(workflow_version_id, created_at);
CREATE INDEX IF NOT EXISTS idx_step_runs_run_status ON step_runs(run_id, status);
CREATE INDEX IF NOT EXISTS idx_attempts_step_no ON step_attempts(step_run_id, attempt_no);
CREATE INDEX IF NOT EXISTS idx_events_run_sequence ON run_events(run_id, sequence_no);
CREATE INDEX IF NOT EXISTS idx_triggers_enabled_fire ON triggers(enabled, next_fire_at);
CREATE INDEX IF NOT EXISTS idx_artifacts_run ON artifacts(run_id);
CREATE INDEX IF NOT EXISTS idx_audit_resource_created ON audit_actions(resource_type, resource_id, created_at);
PRAGMA user_version = 1;
